/** @returns {object|null} geometry record for a property id */
export function geometryFor(id) {
  return ATLANTA_DECATUR_GEOMETRY[String(id || '').trim()] || null;
}

/** @returns {Array<Array<number>>|null} outer [lon,lat] ring of the building */
export function footprintRing(id) {
  return geometryFor(id)?.building?.footprint?.[0] || null;
}

/** @returns {Array<Array<number>>|null} the synthetic parcel ring */
export function parcelRing(id) {
  return geometryFor(id)?.parcel?.ring || null;
}

/** Rows whose footprint lookup found nothing — these degrade to a parcel glow. */
export const ROWS_WITHOUT_FOOTPRINT = Object.freeze([
  'DEMO-ATL-005',
]);
